package com.codearena.controller;
import com.codearena.entity.Problem;import com.codearena.repository.ProblemRepository;import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
import java.util.*;
@RestController public class AdminProblemController {
 @Autowired ProblemRepository problems; ObjectMapper mapper=new ObjectMapper();
 private String json(Object v){try{return mapper.writeValueAsString(v==null?new Object():v);}catch(JsonProcessingException e){throw new IllegalArgumentException("Invalid JSON fields");}}
 @GetMapping("/api/admin/problems") public List<Map<String,Object>> list(){List<Map<String,Object>>out=new ArrayList<>();for(Problem p:problems.findAll(org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"createdAt"))){Map<String,Object>m=new LinkedHashMap<>();m.put("id",p.getId());m.put("title",p.getTitle());m.put("difficulty",p.getDifficulty());m.put("category",p.getCategory());m.put("createdAt",p.getCreatedAt());out.add(m);}return out;}
 @PostMapping("/api/admin/problems") public ResponseEntity<?> save(@RequestBody Map<String,Object>b){String title=(String)b.get("title"),description=(String)b.get("description"),difficulty=(String)b.get("difficulty"),category=(String)b.get("category");if(title==null||description==null||difficulty==null||category==null)return ResponseEntity.badRequest().body(Map.of("error","title, description, difficulty, category are required"));try{String id=(String)b.get("id");Problem p=id!=null&&problems.existsById(id)?problems.findById(id).get():new Problem();if(id!=null)p.setId(id);p.setTitle(title);p.setDescription(description);p.setDifficulty(difficulty);p.setCategory(category);p.setExamples(json(b.get("examples")!=null?b.get("examples"):List.of()));p.setConstraints(json(b.get("constraints")!=null?b.get("constraints"):List.of()));p.setTemplates(json(b.get("templates")!=null?b.get("templates"):Map.of()));p.setTestCases(json(b.get("testCases")!=null?b.get("testCases"):List.of()));p.setTimeLimit(b.get("timeLimit")==null?2000:((Number)b.get("timeLimit")).intValue());p.setMemoryLimit(b.get("memoryLimit")==null?256:((Number)b.get("memoryLimit")).intValue());p=problems.save(p);return ResponseEntity.ok(Map.of("success",true,"problem",p));}catch(Exception e){return ResponseEntity.status(500).body(Map.of("error","Failed to save problem","details",e.getMessage()));}}
}
